export class Vec2ArrayLike {
    static Create(x = 0, y = 0) {
        return [x, y];
    }
    static ApplyMatrix(matrix, vec) {
        return this.ApplyMatrixToRef(matrix, vec, Vec2ArrayLike.Create());
    }
    static ApplyMatrixInPlace(matrix, vec) {
        return this.ApplyMatrixToRef(matrix, vec, vec);
    }
    static ApplyMatrixToRef(matrix, vec, ref) {
        const [x, y] = vec;
        ref[0] = matrix[0] * x + matrix[2] * y;
        ref[1] = matrix[1] * x + matrix[3] * y;
        return ref;
    }
    static RotateAroundPivot(matrix, vec, pivot) {
        const translatedVec = [vec[0] - pivot[0], vec[1] - pivot[1]];
        const rotatedVec = Vec2ArrayLike.ApplyMatrix(matrix, translatedVec);
        return [rotatedVec[0] + pivot[0], rotatedVec[1] + pivot[1]];
    }
    static Add(v1, v2) {
        return this.AddToRef(v1, v2, Vec2ArrayLike.Create());
    }
    static AddInPlace(v1, v2) {
        return this.AddToRef(v1, v2, v1);
    }
    static AddToRef(v1, v2, ref) {
        const [x1, y1] = v1;
        const [x2, y2] = v2;
        ref[0] = x1 + x2;
        ref[1] = y1 + y2;
        return ref;
    }
    static AddScalar(v, scalar) {
        return this.AddScalarToRef(v, scalar, Vec2ArrayLike.Create());
    }
    static AddScalarInPlace(v, scalar) {
        return this.AddScalarToRef(v, scalar, v);
    }
    static AddScalarToRef(v, scalar, ref) {
        const [x, y] = v;
        ref[0] = x + scalar;
        ref[1] = y + scalar;
        return ref;
    }
    static Subtract(v1, v2) {
        return this.SubtractToRef(v1, v2, this.Create());
    }
    static SubtractInPlace(v1, v2) {
        return this.SubtractToRef(v1, v2, v1);
    }
    static SubtractToRef(v1, v2, ref) {
        const [x1, y1] = v1;
        const [x2, y2] = v2;
        ref[0] = x1 - x2;
        ref[1] = y1 - y2;
        return ref;
    }
    static SubtractScalar(v, scalar) {
        return this.SubtractScalarToRef(v, scalar, Vec2ArrayLike.Create());
    }
    static SubtractScalarInPlace(v, scalar) {
        return this.SubtractScalarToRef(v, scalar, v);
    }
    static SubtractScalarToRef(v, scalar, ref) {
        const [x, y] = v;
        ref[0] = x - scalar;
        ref[1] = y - scalar;
        return ref;
    }
    static Multiply(v1, v2) {
        return this.MultiplyToRef(v1, v2, Vec2ArrayLike.Create());
    }
    static MultiplyInPlace(v1, v2) {
        return this.MultiplyToRef(v1, v2, v1);
    }
    static MultiplyToRef(v1, v2, ref) {
        const [x1, y1] = v1;
        const [x2, y2] = v2;
        ref[0] = x1 * x2;
        ref[1] = y1 * y2;
        return ref;
    }
    static MultiplyScalar(v, scalar) {
        return this.MultiplyScalarToRef(v, scalar, Vec2ArrayLike.Create());
    }
    static MultiplyScalarInPlace(v, scalar) {
        return this.MultiplyScalarToRef(v, scalar, v);
    }
    static MultiplyScalarToRef(v, scalar, ref) {
        const [x, y] = v;
        ref[0] = x * scalar;
        ref[1] = y * scalar;
        return ref;
    }
    static Divide(v1, v2) {
        return this.DivideToRef(v1, v2, Vec2ArrayLike.Create());
    }
    static DivideInPlace(v1, v2) {
        return this.DivideToRef(v1, v2, v1);
    }
    static DivideToRef(v1, v2, ref) {
        const [x1, y1] = v1;
        const [x2, y2] = v2;
        ref[0] = x1 / x2;
        ref[1] = y1 / y2;
        return ref;
    }
    static DivideScalar(v, scalar) {
        return this.DivideScalarToRef(v, scalar, Vec2ArrayLike.Create());
    }
    static DivideScalarInPlace(v, scalar) {
        return this.DivideScalarToRef(v, scalar, v);
    }
    static DivideScalarToRef(v, scalar, ref) {
        const [x, y] = v;
        ref[0] = x / scalar;
        ref[1] = y / scalar;
        return ref;
    }
    static Normalize(v) {
        return this.NormalizeToRef(v, Vec2ArrayLike.Create());
    }
    static NormalizeInPlace(v) {
        return this.NormalizeToRef(v, v);
    }
    static NormalizeToRef(v, ref) {
        const len = Vec2ArrayLike.Length(v);
        const [x, y] = v;
        if (len === 0) {
            ref[0] = 0;
            ref[1] = 0;
        }
        else {
            ref[0] = x / len;
            ref[1] = y / len;
        }
        return ref;
    }
    static Lerp(v1, v2, t) {
        return this.LerpToRef(v1, v2, t, Vec2ArrayLike.Create());
    }
    static LerpToRef(v1, v2, t, ref) {
        const [x1, y1] = v1;
        const [x2, y2] = v2;
        ref[0] = x1 + t * (x2 - x1);
        ref[1] = y1 + t * (y2 - y1);
        return ref;
    }
    static Negate(v) {
        return this.NegateToRef(v, Vec2ArrayLike.Create());
    }
    static NegateInPlace(v) {
        return this.NegateToRef(v, v);
    }
    static NegateToRef(v, ref) {
        const [x, y] = v;
        ref[0] = -x;
        ref[1] = -y;
        return ref;
    }
    static Dot(v1, v2) {
        return v1[0] * v2[0] + v1[1] * v2[1];
    }
    static Length(v) {
        return Math.sqrt(v[0] * v[0] + v[1] * v[1]);
    }
    static Distance(v1, v2) {
        return Vec2ArrayLike.Length(Vec2ArrayLike.Subtract(v1, v2));
    }
    static Equals(v1, v2) {
        return v1[0] === v2[0] && v1[1] === v2[1];
    }
    static Clone(v) {
        return [v[0], v[1]];
    }
    static Copy(target, source) {
        target[0] = source[0];
        target[1] = source[1];
        return target;
    }
}
